// Original location-inspired courses, not replicas or licensed venue maps.
const TOUR={
arena:[['Canopy Clash','Costa Rica inspired rainforest · split jungle cover','jungle'],['Amber Fossil Basin','Patagonia inspired dinosaur valley · broken rock cover','fossil'],['Aurora Relay','Iceland inspired research station · long firing lanes','ice'],['Sunken Signal','Pacific island inspired ruins · bridge crossings','reef'],['Afterlight City','Original abandoned city · barricaded streets','city']],
rally:[['Bathurst Mountain Run','Australia · Mount Panorama inspired climbing bends','mountain'],['Suzuka Rhythm Run','Japan · Suzuka inspired linked S bends','sakura'],['Silverstone Airfield Sprint','England · Silverstone inspired fast sweeping turns','airfield'],['Spa Forest Flow','Belgium · Spa inspired forest curves','forest'],['Monza Park Dash','Italy · Monza inspired straights and chicanes','park']],
leap:[['Sydney Harbour Hop','Australia · harbour platforms and sail silhouettes','harbour'],['London Skyline Steps','England · clock towers and rooftop jumps','clock'],['Paris Rooftop Route','France · iron tower skyline and balcony landings','tower'],['New York Skywalk','USA · skyscraper ledges and moving lifts','skyline'],['Tokyo Lantern Leap','Japan · lantern streets and neon roof patrols','lantern']],
tower:[['Kew Glasshouse Keep','England · glasshouses and a double-bend garden path','glass'],['Versailles Fountain Guard','France · formal avenues and winding fountain route','formal'],['Singapore Supertree Sanctuary','Singapore · vertical gardens and overlapping defence lanes','supertree'],['Kenrokuen Pond Citadel','Japan · stone lanterns and a zigzag pond approach','zen'],['Butchart Bloom Bastion','Canada · sunken flower beds and a long terraced approach','flowers']],
dodge:[['Great Barrier Reef Drift','Australia · branching coral and alternating warning zones','branch'],['Belize Blue Reef','Belize · circular reef formations and diagonal showers','bluehole'],['Tubbataha Reef Passage','Philippines · atoll walls and crossing sweeps','atoll'],['Ningaloo Current Run','Australia · fringing reef and drifting currents','fringe'],['New Caledonia Lagoon','New Caledonia · lagoon pinnacles and mixed storm patterns','lagoon']],
maze:[['Giza Sandstone Labyrinth','Egypt · pyramid courts and winding corridors','pyramid'],['Petra Canyon Chambers','Jordan · sandstone chambers joined by passages','petra'],['Angkor Root Hall','Cambodia · a central temple hall and root-lined corridors','roots'],['Venice Canal Puzzle','Italy · braided passages and canal crossings','canal'],['Cusco Terrace Grid','Peru · terraced stone streets and connected plazas','terrace']],
space:[['Sahara Night Orbit','Above Africa · dune horizons and sweeping drone lanes','dunes'],['Amazon Canopy Orbit','Above South America · river curves and close formations','river'],['Himalayan Dawn Orbit','Above Asia · mountain silhouettes and central attack lanes','peaks'],['Pacific Blue Orbit','Above the Pacific · island chains and drifting fleets','islands'],['Antarctic Aurora Orbit','Above Antarctica · ice shelves and flanking formations','aurora']],
memory:[['Sydney Sail Archive','Australia · harbour-inspired symbol vault','sails'],['Paris Ironwork Archive','France · lattice motifs and staggered matching rows','iron'],['Agra Marble Archive','India · domes and a compact matching grid','dome'],['Rome Arch Archive','Italy · arches and offset matching rows','arches'],['Kyoto Lantern Archive','Japan · lantern motifs and a wide matching grid','pagoda']]
};
const TOUR_NOUN={arena:'arena',rally:'racing track',leap:'expedition',tower:'garden',dodge:'reef',maze:'labyrinth',space:'orbit',memory:'landmark vault'};
for(const mode in TOUR)COURSE_SETS[mode]=TOUR[mode].map(r=>r.slice(0,2));
const tourMapBase=courseMap;
courseMap=function(mode=courseMode(),id=selectedCourse(mode)){const m=tourMapBase(mode,id),i=m.baseIndex,d=TOUR[mode][i];m.destination=d[2];m.tourKey=mode+':'+i;m.courseMode=mode;
 const kinds={arena:WORLD_KINDS,rally:['meadow','meadow','lunar','meadow','meadow'],leap:['water','lunar','lunar','lunar','lunar'],tower:['meadow','meadow','meadow','meadow','meadow'],dodge:['water','water','water','water','water'],maze:WORLD_KINDS,space:['lunar','meadow','lunar','water','lunar'],memory:WORLD_KINDS};
 m.terrain=kinds[mode][i];Object.assign(m,ART_WORLDS[m.terrain]);if(mode==='rally'){m.routeWidth=[174,166,200,178,190][i];m.path='#687780'}return m};
const tourCardsBase=battlefieldCards;battlefieldCards=function(){return tourCardsBase().replace(/Choose your [^.]+\./,'Choose your '+TOUR_NOUN[selectedGame().id]+'.').replace(/Course preview/g,'Preview').replace(/View course/g,'View '+TOUR_NOUN[selectedGame().id])};
const tourPreviewBase=openCoursePreview;openCoursePreview=function(mode,id){tourPreviewBase(mode,id);const el=document.querySelector('.preview-instructions');if(el)el.insertAdjacentHTML('beforeend','<p>Original '+TOUR_NOUN[mode]+' inspired by a real-world setting. Stylised scenery and game routes are not exact venue maps.</p>')};
const tourCache=new Map();
function tourLandmark(c,x,y,type,m,s=1){c.save();c.translate(x,y);c.scale(s,s);const line=(p,w=4)=>artLine(c,p,m.top,w),block=(x,y,w,h)=>artBlock(c,x,y,w,h,m,5);
 if(['tower','iron'].includes(type)){artPoly(c,[[-42,0],[0,-125],[42,0],[24,0],[0,-85],[-24,0]],m.top,m.edge,3);for(let y=-25;y>-100;y-=22)line([[-28,y],[28,y]],3);line([[-20,-30],[18,-60],[-12,-80]],3)}
 else if(['pyramid','mountain','peaks','dunes','terrace'].includes(type)){for(let i=0;i<3;i++){const x=i*38-55;artPoly(c,[[x-45,0],[x,-65-i*16],[x+45,0]],m.stone,m.edge,2);artPoly(c,[[x,-65-i*16],[x+45,0],[x+8,-5]],m.top);if(type==='terrace')for(let j=1;j<4;j++)line([[x-35+j*7,-j*12],[x+35-j*7,-j*12]],2)}}
 else if(['harbour','sails'].includes(type)){line([[-70,8],[72,8]],5);for(let i=0;i<3;i++)artPoly(c,[[-60+i*40,0],[-15+i*35,-55-i*15],[12+i*30,0]],'#dae9db',m.edge,2)}
 else if(['glass','dome'].includes(type)){c.fillStyle=m.top;c.beginPath();c.arc(0,-45,45,Math.PI,0);c.fill();block(-48,-45,96,45);for(let i=-30;i<=30;i+=15)line([[i,-65],[i,0]],2);line([[-45,-28],[45,-28]],2)}
 else if(['clock','skyline','city','petra'].includes(type)){for(let i=0;i<3;i++){const h=55+i%2*55;block(-60+i*40,-h,34,h);for(let j=15;j<h;j+=18)roundRect(c,-52+i*40,-j,17,7,1,m.accent)}if(type==='clock'){ellipse(c,-3,-86,12,12,'#f4e1aa');line([[-3,-94],[-3,-86],[3,-82]],2)}}
 else if(['lantern','pagoda','zen','roots'].includes(type)){block(-28,-60,56,60);for(let i=0;i<3;i++)artPoly(c,[[-43+i*7,-i*25-15],[0,-i*25-35],[43-i*7,-i*25-15]],m.top,m.edge,3);if(type==='lantern')for(const x of [-60,60]){line([[x,0],[x,-65]],3);ellipse(c,x,-50,10,16,'#eeae6c')}}
 else if(type==='supertree'){line([[0,0],[0,-90]],12);for(let i=-2;i<=2;i++)line([[0,-40],[i*22,-95]],4);ellipse(c,0,-95,65,17,'#a58eb6');ellipse(c,0,-101,55,12,m.leaf)}
 else if(['branch','bluehole','atoll','fringe','lagoon','reef','islands','canal'].includes(type)){if(type==='bluehole'){ellipse(c,0,-30,65,42,'#12324f');c.strokeStyle='#52c8c5';c.lineWidth=9;c.beginPath();c.ellipse(0,-30,65,42,0,0,7);c.stroke()}else for(let i=0;i<4;i++)artReef(c,-50+i*30,-i%2*20,22,m)}
 else if(type==='arches'){for(let i=0;i<3;i++){block(-65+i*45,-70,40,70);roundRect(c,-58+i*45,-48,25,48,12,m.edge)}}
 else if(type==='airfield'){block(-60,-16,120,16);for(let i=-50;i<50;i+=25)roundRect(c,i,-10,15,4,1,'#ecedde');block(45,-70,22,55)}
 else if(type==='fossil'){artRock(c,0,-15,55,m);for(let i=-2;i<3;i++){c.strokeStyle='#d9d1a9';c.lineWidth=5;c.beginPath();c.ellipse(i*16,-35,12,26,0,Math.PI,Math.PI*2);c.stroke()}}
 else if(type==='ice'||type==='aurora'){artPoly(c,[[-70,0],[-40,-60],[-10,-40],[20,-95],[65,0]],'#98c8d6',m.edge,3);line([[-70,-110],[-25,-130],[20,-105],[70,-120]],8)}
 else{for(let i=0;i<4;i++){artPlant(c,-55+i*35,-20-i%2*25,27,m,i+6);if(['flowers','sakura','formal','park'].includes(type))for(let j=0;j<5;j++)ellipse(c,-65+i*35+j*5,-27-i%2*25,4,4,i%2?'#f2a6bb':'#f2d16e')}if(type==='formal'){ellipse(c,0,12,56,15,m.water);line([[0,7],[0,-35]],5)}}c.restore()}
function tourSurface(g,space){const key=g.map.tourKey+':'+space;if(tourCache.has(key))return tourCache.get(key);const cv=document.createElement('canvas');cv.width=1000;cv.height=650;const c=cv.getContext('2d'),m=g.map,mode=m.courseMode,i=m.baseIndex,rand=artRandom(717+i*83+Object.keys(TOUR).indexOf(mode)*617);let grad=c.createLinearGradient(0,0,0,650);grad.addColorStop(0,space?'#081728':m.light);grad.addColorStop(1,space?'#172e42':m.floor);c.fillStyle=grad;c.fillRect(0,0,1000,650);
 for(let n=0;n<160;n++){c.fillStyle=space?'#d4e8f099':'#deeed015';c.fillRect(rand()*1000,rand()*650,space?2:3,space?2:3)}
 if(mode==='leap'){for(let n=0;n<12;n++){const h=45+rand()*140;roundRect(c,n*90-20,310-h,65,h,2,m.edge+'88')}for(let n=0;n<4;n++)tourLandmark(c,110+n*255,310,m.destination,m,1.2)}
 else if(space){ellipse(c,500,730,670,250,m.water);for(let n=0;n<5;n++)tourLandmark(c,70+n*215,630,m.destination,m,.8)}
 else{for(let n=0;n<6;n++){const x=n%2?940:60,y=145+Math.floor(n/2)*215;tourLandmark(c,x,y,m.destination,m,.7)}if(mode==='tower')for(let n=0;n<9;n++){const x=160+n%3*320,y=120+Math.floor(n/3)*190;ellipse(c,x,y,43,20,m.bush);tourLandmark(c,x,y,m.destination,m,.45)}}
 if(tourCache.size>=80)tourCache.delete(tourCache.keys().next().value);tourCache.set(key,cv);return cv}
miniBackdrop=function(c,g,space=false){c.drawImage(tourSurface(g,space),0,0);const t=g.elapsed||0,m=g.map;if(m.courseMode==='dodge'){for(let n=0;n<15;n++){const x=n*71+Math.sin(t+n)*8,y=650-(n*89+t*22)%700;c.strokeStyle='#b9f4ec77';c.lineWidth=1;c.beginPath();c.arc(x,y,3+n%4,0,7);c.stroke()}for(let n=0;n<5;n++){const x=(n*233+t*18)%1100-50,y=130+n*93;artPoly(c,[[x+12,y],[x-8,y-6],[x-8,y+6]],'#ffc67999')}}else if(space)for(let n=0;n<12;n++)ellipse(c,n*89,(n*61+t*30)%650,1,2,'#d9eeff88')};
// Keep saved slot identifiers and stage progress; each slot retains its distinct mechanics.
if(!game&&!live&&!quiz)navigate('home');
// Preserve five maze layouts independently of their new scenery.
const tourMazeBase=makeRelicMaze;makeRelicMaze=function(g){const terrain=g.map.terrain;g.map.terrain=WORLD_KINDS[g.map.baseIndex];try{return tourMazeBase(g)}finally{g.map.terrain=terrain}};
const tourFinalMap=courseMap;courseMap=function(mode=courseMode(),id=selectedCourse(mode)){const m=tourFinalMap(mode,id);if(mode==='maze'){m.terrain=['meadow','meadow','meadow','water','meadow'][m.baseIndex];Object.assign(m,ART_WORLDS[m.terrain]);if(m.baseIndex<2)Object.assign(m,{floor:'#66503b',light:'#b2946e',stone:'#967354',top:'#d5b68b',path:'#ab8f68',leaf:'#7b8c65',bush:'#4a6146'})}return m};
const tourParents=parents;parents=function(){return tourParents()+'<section class="info-panel"><h2>World Tour inspirations</h2><p>Forty original game settings inspired by real locations. These are curated choices, not a verified popularity ranking for ages 10–12. Routes, scenery and landmarks are stylised original illustrations, not replicas or affiliated venue products.</p><p><a href="https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/media-literacy-research/children/childrens-media-use-and-attitudes-report-2025/childrens-media-literacy-report-2025.pdf" target="_blank" rel="noopener">Ofcom: children’s gaming research</a> · <a href="https://www.redbull.com/al-sq/worlds-best-racing-circuits" target="_blank" rel="noopener">Iconic racing circuits</a> · <a href="https://www.gardenersworld.com/travel/unmissable-gardens-around-the-world/" target="_blank" rel="noopener">Garden inspirations</a> · <a href="https://whc.unesco.org/document/158688.pdf" target="_blank" rel="noopener">UNESCO coral reef heritage</a></p></section>'};
